CONTROLLER_PATH = ROOT / "contracts/verdict_graph_milestone.py"
AUTHORITY_PATH = ROOT / "contracts/verdict_graph_milestone_authority.py"
REGISTRY_PATH = ROOT / "contracts/verdict_graph_milestone_registry.py"
ADJUDICATOR_PATH = ROOT / "contracts/verdict_graph_milestone_adjudicator.py"
VAULT_PATH = ROOT / "evm/contracts/VerdictGraphMilestoneVault.sol"
FRONTEND_CLIENT_PATH = ROOT / "frontend/lib/genlayer/client.ts"
FRONTEND_VAULT_PATH = ROOT / "frontend/lib/genlayer/milestone-vault.ts"
FRONTEND_CONFIG_PATH = ROOT / "frontend/components/milestone-configuration-required.tsx"
