MILESTONE_TEMPLATE_PATH = ROOT / "deploy/milestone-bradbury.template.json"
MILESTONE_ARTIFACT_BUILD_PATH = ROOT / "scripts/build_milestone_deploy_artifact.py"
MILESTONE_DEPLOY_CONTROLLER_PATH = ROOT / "contracts/verdict_graph_milestone_deploy.py"
MILESTONE_DEPLOY_AUTHORITY_PATH = ROOT / "contracts/verdict_graph_milestone_authority_deploy.py"
MILESTONE_DEPLOY_REGISTRY_PATH = ROOT / "contracts/verdict_graph_milestone_registry_deploy.py"
MILESTONE_DEPLOY_ADJUDICATOR_PATH = ROOT / "contracts/verdict_graph_milestone_adjudicator_deploy.py"
MILESTONE_CONTROLLER_PROBE_PATH = ROOT / "scripts/milestone_bradbury_deploy_estimate.mjs"
MILESTONE_VAULT_PROBE_PATH = ROOT / "scripts/milestone_vault_deploy_estimate.mjs"
MILESTONE_VAULT_HASH_PATH = ROOT / "scripts/milestone_vault_runtime_hash.py"
MILESTONE_VERIFY_PATH = ROOT / "scripts/milestone_verify.sh"
MILESTONE_PREFLIGHT_PATH = ROOT / "scripts/milestone_bradbury_preflight.sh"
DIRECT_TEST_PATH = ROOT / "tests/direct/test_milestone_controller.py"
AUTHORITY_TEST_PATH = ROOT / "tests/direct/test_milestone_authority.py"
REGISTRY_TEST_PATH = ROOT / "tests/direct/test_milestone_registry.py"
ADJUDICATOR_TEST_PATH = ROOT / "tests/direct/test_milestone_adjudicator.py"
EVM_TEST_PATH = ROOT / "evm/test/VerdictGraphMilestoneVault.t.sol"


def read(path: Path) -> str:
    if not path.is_file():
        raise SystemExit(f"FAIL missing required release file: {path.relative_to(ROOT)}")
    return path.read_text()


controller = read(CONTROLLER_PATH)
authority = read(AUTHORITY_PATH)
registry = read(REGISTRY_PATH)
adjudicator = read(ADJUDICATOR_PATH)
vault = read(VAULT_PATH)
frontend_client = read(FRONTEND_CLIENT_PATH)
frontend_vault = read(FRONTEND_VAULT_PATH)
frontend_config = read(FRONTEND_CONFIG_PATH)
frontend_actions = read(FRONTEND_ACTIONS_PATH)
frontend_validation = read(FRONTEND_VALIDATION_PATH)
frontend_authority = read(FRONTEND_AUTHORITY_PATH)
frontend_create = read(FRONTEND_CREATE_PATH)
frontend_list = read(FRONTEND_LIST_PATH)
frontend_proof = read(FRONTEND_PROOF_PATH)
frontend_next_config = read(FRONTEND_NEXT_CONFIG_PATH)
frontend_error = read(FRONTEND_ERROR_PATH)
frontend_loading = read(FRONTEND_LOADING_PATH)
frontend_not_found = read(FRONTEND_NOT_FOUND_PATH)
template = read(MILESTONE_TEMPLATE_PATH)
direct_tests = read(DIRECT_TEST_PATH)
evm_tests = read(EVM_TEST_PATH)
